// QELORYX — DesignSystem
// AstryxBrandMark.swift
//
// Typed access to the brand assets in Qeloryx/Resources/Assets.xcassets.
//
// These names previously existed only in the asset catalog, so every call site
// would have had to spell them as string literals — the usual way a rename
// turns into a silently blank image. Keeping them here means a missing asset is
// a one-line fix rather than a hunt.

#if canImport(QeloryxCore)
import QeloryxCore
#endif

import SwiftUI

// MARK: - Asset Names

/// Canonical asset-catalog names for Qeloryx branding.
///
/// The artwork itself is generated by `Tools/branding/build_brand_assets.py`
/// from the Midnight Aurora palette — do not hand-edit the PNGs, regenerate.
public enum AstryxBrandAsset {
    /// Square app mark: aurora Q on the midnight field (dark background).
    public static let mark = "BrandLogo"
    /// Global tint, mirrors `AstryxColors.Semantic.primary`.
    public static let accentColor = "AccentColor"
}

// MARK: - Brand Mark

/// The Qeloryx app mark.
///
/// The PNG has the midnight field baked in, so this reads correctly on dark
/// surfaces and is inset with a rounded corner when shown as a badge. For use
/// on an arbitrary background, prefer the generated lockup in `Docs/Branding/`.
public struct AstryxBrandMark: View {

    public enum Size: CGFloat {
        case small = 24
        case medium = 40
        case large = 64
        case hero = 96
    }

    private let size: CGFloat
    private let cornerRadius: CGFloat?

    public init(_ size: Size = .medium) {
        self.size = size.rawValue
        self.cornerRadius = size.rawValue * 0.2237 // iOS squircle ratio, for badge use
    }

    public init(pointSize: CGFloat, cornerRadius: CGFloat? = nil) {
        self.size = pointSize
        self.cornerRadius = cornerRadius
    }

    public var body: some View {
        Image(AstryxBrandAsset.mark)
            .resizable()
            .interpolation(.high)
            .antialiased(true)
            .aspectRatio(1, contentMode: .fit)
            .frame(width: size, height: size)
            .clipShape(RoundedRectangle(cornerRadius: cornerRadius ?? 0, style: .continuous))
            .accessibilityLabel("Qeloryx")
            .accessibilityAddTraits(.isImage)
    }
}

// MARK: - Wordmark

/// The Qeloryx wordmark in Space Grotesk, with tracking opened to match the
/// generated lockups.
///
/// Falls back to the system rounded face if the font is not registered via
/// `UIAppFonts` — the same fallback `AstryxTypography.Logo` documents, but the
/// font is now actually bundled, so the fallback should not be hit.
public struct AstryxWordmark: View {

    private let size: CGFloat
    private let color: Color

    public init(size: CGFloat = 24, color: Color = AstryxColors.iceWhite) {
        self.size = size
        self.color = color
    }

    public var body: some View {
        Text("QELORYX")
            .font(.custom("SpaceGrotesk-Bold", size: size, relativeTo: .title))
            .tracking(size * 0.055)
            .foregroundColor(color)
            .accessibilityAddTraits(.isHeader)
    }
}

// MARK: - Lockup

/// Horizontal lockup: mark + wordmark, the arrangement used in the README and
/// the generated brand sheet.
public struct AstryxBrandLockup: View {

    private let markSize: CGFloat
    private let textSize: CGFloat
    private let color: Color

    /// - Parameter height: overall lockup height; mark and text are derived
    ///   from it so the proportions match `build_brand_assets.py`
    ///   (mark ink = 1.30x cap height, gap = 0.40x cap height).
    public init(height: CGFloat = 44, color: Color = AstryxColors.iceWhite) {
        self.markSize = height * 0.86
        self.textSize = height * 0.42
        self.color = color
    }

    public var body: some View {
        HStack(spacing: markSize * 0.30) {
            AstryxBrandMark(pointSize: markSize, cornerRadius: 0)
            AstryxWordmark(size: textSize, color: color)
        }
        .accessibilityElement(children: .combine)
        .accessibilityLabel("Qeloryx")
    }
}

// MARK: - Preview

struct AstryxBrandMark_Previews: PreviewProvider {
    static var previews: some View {
        VStack(spacing: 32) {
            AstryxBrandLockup(height: 56)
            HStack(spacing: 20) {
                AstryxBrandMark(.small)
                AstryxBrandMark(.medium)
                AstryxBrandMark(.large)
                AstryxBrandMark(.hero)
            }
        }
        .padding()
        .background(AstryxColors.midnight)
        .previewLayout(.sizeThatFits)
    }
}
